router = APIRouter(prefix="/v1/orders", tags=["orders"])

@router.delete("/{order_id}", status_code=204)
def delete_order(order_id: UUID, hard: bool = False, db: Session = Depends(get_db)):
    order = db.get(Order, order_id)
    if order is None:
        raise HTTPException(404, "order not found")
    if order.status == "shipped" and not hard:
        raise HTTPException(423, "shipped orders cannot be deleted")
    if hard:
        db.delete(order)
    else:
        order.deleted_at = utcnow()
    db.commit()

def test_delete_returns_204(client):
    r = client.delete(f"/v1/orders/{seed_order.id}")
    assert r.status_code == 204

def test_delete_unknown_id_404(client):
    r = client.delete("/v1/orders/00000000-0000-0000-0000-000000000000")
    assert r.status_code == 404

def test_delete_shipped_423(client):
    seed_order.status = "shipped"
    r = client.delete(f"/v1/orders/{seed_order.id}")
    assert r.status_code == 423

