export function parse(input: string): string[][] {
  const rows: string[][] = [];
  let field = "", row: string[] = [], inQuotes = false;
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (inQuotes) {
      if (ch === '"' && input[i + 1] === '"') { field += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else field += ch;
    } else if (ch === '"') inQuotes = true;
    else if (ch === ",") { row.push(field); field = ""; }
    else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && input[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((c) => c !== "")) rows.push(row);
      row = [];
    } else field += ch;
  }
  if (field !== "" || row.length) { row.push(field); rows.push(row); }
  return rows;
}

import { parse } from "./csv.ts";
import { assertEquals, assertThrows } from "jsr:@std/assert@1";

Deno.test("single line", () => assertEquals(parse("a,b"), [["a", "b"]]));
Deno.test("quoted fields", () => assertEquals(parse('a,"b,c",d'), [["a", "b,c", "d"]]));
Deno.test("crlf", () => assertEquals(parse("a\r\nb"), [["a"], ["b"]]));
Deno.test("skips empty lines", () => assertEquals(parse("a\n\nb"), [["a"], ["b"]]));
Deno.test("throws on unbalanced quotes", () => assertThrows(() => parse('a,"b')));

