export type Token = { kind: "word" | "number" | "punct"; value: string };

export function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  for (const m of input.matchAll(/\d+|\w+|[^\s]/g)) {
    const value = m[0];
    tokens.push({ kind: /^\d/.test(value) ? "number" : /\w/.test(value) ? "word" : "punct", value });
  }
  return tokens;
}

