"""Seed dev with deterministic demo data."""
import click, faker
from app.db import session
from app.models import User, Order

@click.command()
@click.option("--users", default=5000)
@click.option("--orders-per-user", default=2)
def seed(users, orders_per_user):
    f = faker.Faker()
    for i in range(users):
        u = User(email=f"demo-{i}@example.com", name=f.name())
        session.add(u)
        for _ in range(orders_per_user):
            session.add(Order(user=u, total=f.pydecimal(2, 2)))
    session.commit()
    print(f"inserted {users} users, {users * orders_per_user} orders")
